import type { TopicId } from "./topics"

export interface Question {
  id: string
  topic: TopicId
  /** Arabic sentence; "___" marks the blank. */
  sentence: string
  /** First entry is shown as the model answer. Comparison ignores diacritics. */
  answers: string[]
  /** Optional answer choices, used by the vocabulary multiple-choice unit. */
  choices?: string[]
  /** Dictionary/base form to modify, or a subject/trigger when the blank is a particle. */
  cue?: string
  english: string
  explanation: string
}

type Raw = Omit<Question, "id" | "topic">

